class LmdbNativeCostModelPersistenceTest {

	@TempDir
	Path dataDir;

	private static final LmdbNativeRegimeKey WARM = LmdbNativeRegimeKey.STEADY;

	private LmdbNativeStoreCostModel store(AtomicLong wall, long indexGeneration) {
		LmdbNativeCostModelContext context = new LmdbNativeCostModelContext(dataDir,
				UUID.nameUUIDFromBytes(new byte[] { 7 }), () -> 0L, () -> "DISABLED", () -> 0L,
				() -> indexGeneration);
		return new LmdbNativeStoreCostModel(context, LmdbNativePosteriorConfig.defaults(),
				LmdbNativeProbeConfig.defaults(), wall::get, wall::get);
	}

	private static LmdbNativeCostPosteriorStore.ExactKey key(String family) {
		return LmdbNativeCostPosteriorStore.ExactKey.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT,
				LmdbNativePhysicalVariantKey.builder(family).build());
	}

	@Test
	void evidenceAndCooldownsSurviveARestartWithCappedConfidence() throws IOException {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeStoreCostModel original = store(wall, 3L);
		LmdbNativeCostPosteriorStore.ExactKey arm = key("nestedLoop");
		for (int i = 0; i < 50; i++) {
			original.posteriors().updateCompleted(arm, Math.log(2_000_000.0), 1.0, 0L, wall.get());
		}
		original.posteriors().updateCensored(key("wcoj"), Math.log(9_000_000.0), 0L, wall.get());
		original.probeScheduler().censored(key("wcoj").variant(), WARM, 0L, false);
		original.persistence().persistIfDue(true);
		assertTrue(Files.isRegularFile(dataDir.resolve(LmdbNativeCostModelPersistence.FILE_NAME)));

		LmdbNativeCostPosteriorStore.Reading fresh = original.posteriors().read(arm, 0L, wall.get());
		LmdbNativeStoreCostModel reloaded = store(wall, 3L);
		LmdbNativeCostPosteriorStore.Reading restored = reloaded.posteriors().read(arm, 0L, wall.get());
		assertTrue(restored.exactPresent(), "completed evidence survives the restart");
		assertEquals(fresh.meanLog(), restored.meanLog(), 1e-9, "the learned mean survives exactly");
		assertTrue(restored.epistemicVariance() >= fresh.epistemicVariance(),
				"loaded precision is capped — never more confident than the live state was");
		assertEquals(1, reloaded.posteriors().read(key("wcoj"), 0L, wall.get()).exact().censoredCount,
				"censored evidence survives — a restart must not repeat a rejected probe");
		assertFalse(reloaded.probeScheduler().mayProbe(key("wcoj").variant(), WARM, 0L),
				"an unexpired cooldown survives the restart");
	}

	@Test
	void fingerprintMismatchAndCorruptionStartCold() throws IOException {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeStoreCostModel original = store(wall, 3L);
		original.posteriors().updateCompleted(key("nestedLoop"), 1.0, 1.0, 0L, wall.get());
		original.persistence().persistIfDue(true);

		LmdbNativeStoreCostModel differentIndexGeneration = store(wall, 4L);
		assertFalse(differentIndexGeneration.posteriors().read(key("nestedLoop"), 0L, wall.get()).anyEvidence(),
				"an index-generation fingerprint mismatch starts cold");

		Path sidecar = dataDir.resolve(LmdbNativeCostModelPersistence.FILE_NAME);
		byte[] bytes = Files.readAllBytes(sidecar);
		bytes[bytes.length - 3] ^= 0x5A;
		Files.write(sidecar, bytes);
		LmdbNativeStoreCostModel corrupted = store(wall, 3L);
		assertFalse(corrupted.posteriors().read(key("nestedLoop"), 0L, wall.get()).anyEvidence(),
				"a CRC mismatch starts cold");
	}

	@Test
	void staleEvidenceLosesPrecisionAndExpiredCooldownsAreDropped() throws IOException {
		AtomicLong wall = new AtomicLong(1_000_000L);
		LmdbNativeStoreCostModel original = store(wall, 3L);
		LmdbNativeCostPosteriorStore.ExactKey arm = key("nestedLoop");
		for (int i = 0; i < 50; i++) {
			original.posteriors().updateCompleted(arm, 1.0, 1.0, 0L, wall.get());
		}
		original.probeScheduler().censored(key("wcoj").variant(), WARM, 0L, false);
		original.persistence().persistIfDue(true);
		LmdbNativeCostPosteriorStore.Reading fresh = original.posteriors().read(arm, 0L, wall.get());

		wall.addAndGet(30L * 24 * 3_600_000L); // a month later
		LmdbNativeStoreCostModel reloaded = store(wall, 3L);
		LmdbNativeCostPosteriorStore.Reading stale = reloaded.posteriors().read(arm, 0L, wall.get());
		assertTrue(stale.exactPresent(), "old-but-compatible evidence still loads");
		assertTrue(stale.epistemicVariance() > fresh.epistemicVariance() * 2,
				"a month of staleness must substantially reduce loaded precision");
		assertTrue(reloaded.probeScheduler().mayProbe(key("wcoj").variant(), WARM, 0L),
				"an expired cooldown is dropped at restore");
	}

	@Test
	void storeShutdownFlushesItsCostModel() throws IOException {
		Path storeDir = dataDir.resolve("shutdown-flush");
		SailRepository repository = new SailRepository(
				new LmdbStore(storeDir.toFile(), new LmdbStoreConfig("spoc,posc,ospc")));
		try {
			SimpleValueFactory vf = SimpleValueFactory.getInstance();
			IRI p = vf.createIRI("urn:test:p");
			IRI q = vf.createIRI("urn:test:q");
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.add(vf.createIRI("urn:test:s"), p, vf.createIRI("urn:test:o"));
				connection.add(vf.createIRI("urn:test:o"), q, vf.createLiteral("value"));
				connection.prepareTupleQuery(QueryLanguage.SPARQL,
						"SELECT * WHERE { ?s <urn:test:p> ?o . ?o <urn:test:q> ?v }")
						.evaluate()
						.stream()
						.count();
			}
			assertFalse(Files.exists(storeDir.resolve(LmdbNativeCostModelPersistence.FILE_NAME)),
					"the below-threshold evidence should still be pending before shutdown");
		} finally {
			repository.shutDown();
		}
		assertTrue(Files.isRegularFile(storeDir.resolve(LmdbNativeCostModelPersistence.FILE_NAME)),
				"store shutdown must force the learned cost model to durable storage");
	}
}
